/// Create a callback for streaming live output to this spinner.
///
/// Returns `Some(callback)` if the spinner supports live output streaming
/// (e.g., interactive spinners backed by a progress bar). Returns `None`
/// for mock/hidden/noop spinners.
fn create_output_callback(
    &self,
    base_message: &str,
