            },
            skip_behavior: SkipBehavior::SkipWithDependents,
            ..Default::default()
        };

        let ctx = InterpolationContext::new();
        let mut skipped_names = Vec::new();
        runner
            .run_with_progress(
                &options,
                &ctx,
                &HashMap::new(),
